import unittest
from candidate import fib

class TestFibonacci(unittest.TestCase):
    def test_fibonacci_zero(self):
        self.assertEqual(fib(0), 0)

    def test_fibonacci_one(self):
        self.assertEqual(fib(1), 1)

    def test_fibonacci_small_positive(self):
        self.assertEqual(fib(2), 1)

    def test_fibonacci_bigger_positive(self):
        self.assertEqual(fib(10), 55)

    def test_fibonacci_negative(self):
        with self.assertRaises(TypeError):
            fib(-1)

    def test_fibonacci_non_integer(self):
        with self.assertRaises(TypeError):
            fib(1.5)

    def test_fibonacci_none(self):
        with self.assertRaises(TypeError):
            fib(None)

    def test_fibonacci_string(self):
        with self.assertRaises(TypeError):
            fib("10")

    def test_fibonacci_list(self):
        with self.assertRaises(TypeError):
            fib([10])

    def test_fibonacci_dict(self):
        with self.assertRaises(TypeError):
            fib({"a": 10})

if __name__ == '__main__':
    unittest.main()
